    options: { relationType: { family: "قريب — بالنسب أو المصاهرة أو التبني أو الولاية القانونية", partner: "زوج/زوجة المستلم أو شريك/شريكة حياة مسجّل أو خطيب/خطيبة", familylike: "شخص تربطه بالمستلم علاقة طويلة الأمد شبيهة بالقرابة", other: "شخص آخر" }, purpose: { home: "دفعة أولى أو رسوم إتمام لشراء منزل", other: "غرض آخر" } },
