      payment: { delivery: "كله عند التسليم", advance: "كله قبل التسليم", deposit: "دفعة مقدمة الآن والباقي عند التسليم" },
      delivery: { pickup: "يستلم المشتري البضائع بنفسه", seller: "يسلّم البائع البضائع", carrier: "يشحن البائع البضائع بواسطة ناقل" },
      freight: { buyer: "يدفع المشتري الشحن", seller: "يدفع البائع الشحن" },
